-- The schema a fresh database got from servers before Drizzle (commit edccef9), dumped from sqlite_master.
CREATE TABLE agent_credentials (agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, name TEXT NOT NULL, hosts TEXT NOT NULL, value TEXT NOT NULL, placeholder TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_used_at TEXT, PRIMARY KEY (agent_id, name));
CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, avatar TEXT NOT NULL, description TEXT NOT NULL, instructions TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, enabled INTEGER NOT NULL, tools TEXT NOT NULL, skills TEXT NOT NULL, mcp_servers TEXT NOT NULL, delegates TEXT NOT NULL DEFAULT '[]', inference TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, shared_skills TEXT NOT NULL DEFAULT '[]', desktop_model TEXT, review_model TEXT, review TEXT, shared_memory INTEGER NOT NULL DEFAULT 0);
CREATE TABLE conversations (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, title TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE credential_authorities (agent_id TEXT PRIMARY KEY REFERENCES agents(id) ON DELETE CASCADE, certificate TEXT NOT NULL, key TEXT NOT NULL);
CREATE TABLE credential_requests (agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, name TEXT NOT NULL, hosts TEXT NOT NULL, reason TEXT NOT NULL, requested_at TEXT NOT NULL, PRIMARY KEY (agent_id, name));
CREATE TABLE credential_uses (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_id TEXT NOT NULL, name TEXT NOT NULL, at TEXT NOT NULL, method TEXT NOT NULL, host TEXT NOT NULL, path TEXT NOT NULL, status INTEGER, FOREIGN KEY (agent_id, name) REFERENCES agent_credentials(agent_id, name) ON DELETE CASCADE);
CREATE TABLE credentials (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE desktop_control (agent_id TEXT PRIMARY KEY REFERENCES agents(id) ON DELETE CASCADE, holder TEXT NOT NULL, changes INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE executions (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, schedule_id TEXT REFERENCES schedules(id) ON DELETE SET NULL, submission_id TEXT, request_id TEXT NOT NULL, prompt TEXT, reply_to TEXT, status TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, attachments TEXT, attachments_digest TEXT);
CREATE TABLE group_chats (id TEXT PRIMARY KEY, name TEXT NOT NULL, bot_turns INTEGER NOT NULL DEFAULT 0, paused INTEGER NOT NULL DEFAULT 0, awaiting_answers TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE group_members (group_id TEXT NOT NULL REFERENCES group_chats(id) ON DELETE CASCADE, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, joined_at TEXT NOT NULL, conversation_id TEXT, cursor INTEGER NOT NULL DEFAULT 0, pending INTEGER NOT NULL DEFAULT 0, pending_bot_started INTEGER NOT NULL DEFAULT 0, summary TEXT, PRIMARY KEY (group_id, agent_id));
CREATE TABLE group_turns (execution_id TEXT PRIMARY KEY REFERENCES executions(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES group_chats(id) ON DELETE CASCADE, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, through INTEGER NOT NULL, bot_started INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE learned_changes (id TEXT PRIMARY KEY, agent_id TEXT, actor TEXT NOT NULL, target TEXT NOT NULL, target_id TEXT NOT NULL, action TEXT NOT NULL, before_state TEXT, after_state TEXT, source TEXT, reverts_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE mcp_servers (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, enabled INTEGER NOT NULL, agent_id TEXT REFERENCES agents(id) ON DELETE CASCADE, oauth_client_id TEXT);
CREATE TABLE memories (id TEXT PRIMARY KEY, agent_id TEXT REFERENCES agents(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source TEXT);
CREATE TABLE pending_reviews (execution_id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, conversation_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE provider_credentials (provider TEXT PRIMARY KEY, type TEXT NOT NULL CHECK (type IN ('api_key', 'oauth')), value TEXT NOT NULL);
CREATE TABLE review_counters (agent_id TEXT PRIMARY KEY REFERENCES agents(id) ON DELETE CASCADE, skill_rounds INTEGER NOT NULL DEFAULT 0, memory_rounds INTEGER NOT NULL DEFAULT 0);
CREATE TABLE review_results (execution_id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, change_ids TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE schedules (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, name TEXT NOT NULL, prompt TEXT NOT NULL, cron TEXT, timezone TEXT NOT NULL, run_at TEXT, enabled INTEGER NOT NULL, next_run_at TEXT, created_at TEXT NOT NULL, created_by_agent_id TEXT);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE skill_documents (skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, path TEXT NOT NULL, content TEXT NOT NULL, PRIMARY KEY (skill_id, path));
CREATE TABLE skills (id TEXT PRIMARY KEY, name TEXT NOT NULL, instructions TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, agent_id TEXT REFERENCES agents(id) ON DELETE CASCADE, description TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL DEFAULT 'owner', source_execution_id TEXT, use_count INTEGER NOT NULL DEFAULT 0, last_used_at TEXT, state TEXT NOT NULL DEFAULT 'active', pinned INTEGER NOT NULL DEFAULT 0);
CREATE INDEX credential_uses_by_credential ON credential_uses(agent_id, name, id);
CREATE INDEX credential_uses_by_time ON credential_uses(at);
CREATE UNIQUE INDEX executions_conversation_request ON executions(conversation_id, request_id);
CREATE INDEX learned_changes_agent ON learned_changes(agent_id, created_at);
